const err = $json;
const workflow = err.workflow?.name ?? 'Workflow inconnu';
const node     = err.execution?.lastNodeExecuted ?? 'N/A';
const message  = err.execution?.error?.message ?? 'Erreur inconnue';
const ts       = new Date().toISOString();
return [{
  json: {
    workflow,
    node,
    message,
    timestamp: ts,
    resume_url: 'http://localhost:5678/executions'
  }
}];
